// src/utils/themeDetection.js

const THEME_STORAGE_KEY = 'user-theme-preference';

/**
 * Detects the user's preferred color scheme from the system settings.
 * Returns 'dark' or 'light'.
 */
export function detectSystemTheme() {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    // Default to light if no window or matchMedia support
    return 'light';
  }
  const darkQuery = window.matchMedia('(prefers-color-scheme: dark)');
  return darkQuery.matches ? 'dark' : 'light';
}

/**
 * Retrieves the stored user theme preference from localStorage.
 * Returns 'dark', 'light', or null if no preference stored.
 */
export function getStoredTheme() {
  if (typeof window === 'undefined' || typeof window.localStorage === 'undefined') {
    return null;
  }
  try {
    const stored = window.localStorage.getItem(THEME_STORAGE_KEY);
    if (stored === 'dark' || stored === 'light') {
      return stored;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Stores the user theme preference in localStorage.
 * Accepts 'dark' or 'light' as valid values.
 */
export function storeTheme(theme) {
  if (typeof window === 'undefined' || typeof window.localStorage === 'undefined') {
    return;
  }
  if (theme !== 'dark' && theme !== 'light') {
    throw new Error(`Invalid theme value: ${theme}`);
  }
  try {
    window.localStorage.setItem(THEME_STORAGE_KEY, theme);
  } catch {
    // Fail silently on storage errors
  }
}

/**
 * Gets the effective theme for the user.
 * Priority:
 * 1. Stored user preference
 * 2. System preference
 * Returns 'dark' or 'light'.
 */
export function getEffectiveTheme() {
  const stored = getStoredTheme();
  if (stored) {
    return stored;
  }
  return detectSystemTheme();
}

