const THEME_KEY = 'user-theme-preference';

/**
 * Detects the user's preferred color scheme using the
 * window.matchMedia API.
 * Returns 'dark' or 'light'.
 */
function detectSystemTheme() {
  if (typeof window !== 'undefined' && window.matchMedia) {
    if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      return 'dark';
    }
    return 'light';
  }
  // Default fallback
  return 'light';
}

/**
 * Retrieves the stored user theme preference from localStorage.
 * Returns 'dark', 'light', or null if no preference is stored.
 */
function getStoredTheme() {
  if (typeof window === 'undefined' || !window.localStorage) {
    return null;
  }
  try {
    const theme = window.localStorage.getItem(THEME_KEY);
    if (theme === 'dark' || theme === 'light') {
      return theme;
    }
  } catch {
    // ignore errors (e.g. private mode restrictions)
  }
  return null;
}

/**
 * Stores the user's theme preference in localStorage.
 * Accepts 'dark' or 'light' as valid values.
 */
function setStoredTheme(theme) {
  if (typeof window === 'undefined' || !window.localStorage) {
    return;
  }
  if (theme !== 'dark' && theme !== 'light') {
    throw new Error(`Invalid theme value: ${theme}`);
  }
  try {
    window.localStorage.setItem(THEME_KEY, theme);
  } catch {
    // ignore errors (e.g. private mode restrictions)
  }
}

/**
 * Returns the effective theme to use:
 * - If user has stored preference, return it.
 * - Otherwise, detect system preference and return it.
 */
function getEffectiveTheme() {
  const stored = getStoredTheme();
  if (stored) {
    return stored;
  }
  return detectSystemTheme();
}

module.exports = {
  detectSystemTheme,
  getStoredTheme,
  setStoredTheme,
  getEffectiveTheme,
};

