import React, { useEffect, useState } from 'react';

const THEME_KEY = 'user-theme-preference';
const DARK_CLASS = 'dark-theme';
const LIGHT_CLASS = 'light-theme';

function getPreferredTheme() {
  // Check localStorage
  const stored = localStorage.getItem(THEME_KEY);
  if (stored === DARK_CLASS || stored === LIGHT_CLASS) {
    return stored;
  }
  // Check system preference
  if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
    return DARK_CLASS;
  }
  return LIGHT_CLASS;
}

function applyTheme(theme) {
  const root = document.documentElement;
  root.classList.remove(DARK_CLASS, LIGHT_CLASS);
  root.classList.add(theme);
}

export default function ThemeToggle() {
  const [theme, setTheme] = useState(getPreferredTheme);

  useEffect(() => {
    applyTheme(theme);
    localStorage.setItem(THEME_KEY, theme);
  }, [theme]);

  // Listen to system theme changes and update only if user hasn't manually set theme
  useEffect(() => {
    function onSystemThemeChange(e) {
      const stored = localStorage.getItem(THEME_KEY);
      if (stored !== DARK_CLASS && stored !== LIGHT_CLASS) {
        const newTheme = e.matches ? DARK_CLASS : LIGHT_CLASS;
        setTheme(newTheme);
      }
    }
    const mql = window.matchMedia('(prefers-color-scheme: dark)');
    mql.addEventListener
      ? mql.addEventListener('change', onSystemThemeChange)
      : mql.addListener(onSystemThemeChange);
    return () => {
      mql.removeEventListener
        ? mql.removeEventListener('change', onSystemThemeChange)
        : mql.removeListener(onSystemThemeChange);
    };
  }, []);

  function toggleTheme() {
    setTheme((current) => (current === DARK_CLASS ? LIGHT_CLASS : DARK_CLASS));
  }

  return (
    <button
      aria-label={`Switch to ${theme === DARK_CLASS ? 'light' : 'dark'} theme`}
      onClick={toggleTheme}
      type="button"
      style={{
        cursor: 'pointer',
        padding: '0.5em 1em',
        background: 'none',
        border: '1px solid currentColor',
        borderRadius: '4px',
        fontSize: '1rem',
        color: 'inherit',
      }}
    >
      {theme === DARK_CLASS ? '🌙 Dark' : '☀️ Light'}
    </button>
  );
}

