// Simple syntax regex patterns for Python, Shell, and YAML (common in project)
const syntaxPatterns = {
  py: {
    keyword:
      /\b(False|None|True|and|as|assert|async|await|break|class|continue|def|del|elif|else|except|finally|for|from|global|if|import|in|is|lambda|nonlocal|not|or|pass|raise|return|try|while|with|yield)\b/g,
    string: /(\"\"\"[\s\S]*?\"\"\"|\'\'\'[\s\S]*?\'\'\'|\".*?\"|\'.*?\')/g,
    comment: /#.*$/gm,
    number: /\b\d+(\.\d+)?\b/g,
    function: /\bdef (\w+)\b/g,
    operator: /[+\-*/%=<>!&|^~]/g,
    variable: /\b(self|cls)\b/g,
  },
  sh: {
    keyword:
      /\b(if|then|else|elif|fi|for|while|in|do|done|case|esac|function|select|until|break|continue|return|exit|export|local|readonly|declare|typeset)\b/g,
    string: /(\".*?\"|\'.*?\')/g,
    comment: /#.*$/gm,
    number: /\b\d+\b/g,
    function: /\b(\w+)\s*\(\s*\)\s*{/g,
    operator: /[+\-*/%=<>!&|]/g,
    variable: /\$\w+/g,
  },
  yml: {
    keyword: /^(---|\.{3})$/gm,
    string: /(\".*?\"|\'.*?\')/g,
    comment: /#.*/g,
    number: /\b\d+(\.\d+)?\b/g,
    operator: /[:\-?]/g,
    variable: /\b(true|false|null|yes|no)\b/gi,
  },
  txt: {}, // plain text, no styling
  md: {}, // markdown - no syntax highlighting here
  xml: {
    keyword: /<\/?[\w\s="'-:.]+\/?>/g,
    string: /\".*?\"/g,
    comment: /<!--[\s\S]*?-->/g,
    number: /\b\d+\b/g,
    operator: /[=<>\/]/g,
  },
  iml: {
    keyword: /<\/?[\w\s="'-:.]+\/?>/g,
    string: /\".*?\"/g,
    comment: /<!--[\s\S]*?-->/g,
    number: /\b\d+\b/g,
    operator: /[=<>\/]/g,
  },
};

function escapeHtml(text) {
  return text.replace(/[&<>"']/g, function (m) {
    switch (m) {
      case '&':
        return '&amp;';
      case '<':
        return '&lt;';
      case '>':
        return '&gt;';
      case '"':
        return '&quot;';
      case "'":
        return '&#39;';
      default:
        return m;
    }
  });
}

// Highlight text by applying spans with styles
function highlightText(text, langPatterns, colors) {
  if (!langPatterns) return escapeHtml(text);

  // Order matters: comments first, then strings, keywords, numbers, functions, variables, operators
  // We'll tokenize the text by splitting on these patterns and wrapping matches

  // We'll build an array of tokens with type and content
  const tokens = [];

  // We'll iterate through the text and find matches for all patterns, then sort by index
  const matches = [];

  for (const [type, pattern] of Object.entries(langPatterns)) {
    if (!pattern || typeof pattern.exec !== 'function') continue;
    let match;
    pattern.lastIndex = 0;
    while ((match = pattern.exec(text)) !== null) {
      matches.push({
        type,
        start: match.index,
        end: match.index + match[0].length,
        text: match[0],
      });
      // Prevent infinite loops for zero-length matches
      if (match.index === pattern.lastIndex) pattern.lastIndex++;
    }
  }

  // Sort matches by start index
  matches.sort((a, b) => a.start - b.start);

  // Merge overlapping matches by priority (comment > string > keyword > function > variable > number > operator)
  const priority = {
    comment: 1,
    string: 2,
    keyword: 3,
    function: 4,
    variable: 5,
    number: 6,
    operator: 7,
  };

  const filtered = [];
  let lastEnd = 0;

  for (let i = 0; i < matches.length; i++) {
    const m = matches[i];
    // Skip if overlapped by higher priority match
    let overlapped = false;
    for (let j = 0; j < filtered.length; j++) {
      const f = filtered[j];
      if (
        (m.start < f.end && m.end > f.start) && // overlap
        priority[m.type] >= priority[f.type]
      ) {
        overlapped = true;
        break;
      }
    }
    if (!overlapped) filtered.push(m);
  }

  // Now build tokens from filtered matches
  let pos = 0;
  for (const m of filtered) {
    if (pos < m.start) {
      tokens.push({
        type: 'plain',
        text: text.slice(pos, m.start),
      });
    }
    tokens.push({
      type: m.type,
      text: m.text,
    });
    pos = m.end;
  }
  if (pos < text.length) {
    tokens.push({
      type: 'plain',
      text: text.slice(pos),
    });
  }

  // Build HTML string with spans
  return tokens
    .map(({ type, text }) => {
      const escaped = escapeHtml(text);
      if (type === 'plain') return escaped;
      const color = colors[type] || colors.text;
      return `<span style="color:${color}">${escaped}</span>`;
    })
    .join('');
}

