/* src/styles/animations.css */

/* Define smooth transition for theme-related properties */
:root {
  --transition-duration: 300ms;
  --transition-easing: cubic-bezier(0.4, 0, 0.2, 1);
}

/* Apply smooth transitions to color and background-color for theme changes */
body, 
body * {
  transition-property: background-color, color, border-color, box-shadow, fill, stroke;
  transition-duration: var(--transition-duration);
  transition-timing-function: var(--transition-easing);
  transition-delay: 0ms;
  will-change: background-color, color, border-color, box-shadow, fill, stroke;
}

/* Respect user preference for reduced motion */
@media (prefers-reduced-motion: reduce) {
  body, 
  body * {
    transition-property: none !important;
    transition-duration: 0ms !important;
    animation: none !important;
    will-change: auto !important;
  }
}
